from typing import List
from collections import deque

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        n = len(status)
        has_box = [False] * n
        has_key = [False] * n
        visited = [False] * n
        queue = deque()

        for b in initialBoxes:
            has_box[b] = True

        for b in initialBoxes:
            if status[b] == 1:
                queue.append(b)
                visited[b] = True

        total_candies = 0

        while queue:
            box = queue.popleft()
            total_candies += candies[box]

            for key_idx in keys[box]:
                if not has_key[key_idx]:
                    has_key[key_idx] = True
                    if has_box[key_idx] and not visited[key_idx]:
                        queue.append(key_idx)
                        visited[key_idx] = True

            for contained in containedBoxes[box]:
                if not has_box[contained]:
                    has_box[contained] = True
                    if has_key[contained] and not visited[contained]:
                        queue.append(contained)
                        visited[contained] = True

        return total_candies
